"""Author immutable v6 investigations with diegetic rules and a final action.

Existing editions, media facts, schema and saves are never rewritten.
Each puzzle specifies its accessible rule document and the sources needed to
derive the answer. The tenth lock executes the case's resolution, not a quiz.
"""
import copy
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SRC = ROOT / 'apps/ghostdesk/src'
cases = copy.deepcopy(json.loads((SRC / 'ten-stage-cases.json').read_text()))
walkthrough = []


def start(index, folders, purpose, first):
    global c, cid, names
    c = cases[index]
    cid = c['caseId']
    names = folders.split('|')
    c['versionId'] = cid + '-v6'
    c['estimatedMinutes'] = [55, 60, 65, 60, 65][index]
    c['description'] = purpose
    # Replace only references to puzzle IDs within this new edition.
    for i, p in enumerate(c['puzzles'], 1):
        old = p['id']
        new = f'{cid}-p{i}-v6'
        c.update(json.loads(json.dumps(c, ensure_ascii=False).replace(old, new)))
    for i, p in enumerate(c['puzzles']):
        p.update(inputMode='text', ignoreCase=True, stageTitle=names[i])
        p.pop('choices', None)
        p.pop('visualId', None)
        f = next(f for f in c['files'] if f.get('puzzleId') == p['id'])
        f['title'] = names[i]
        f['text'] = '잠금이 해제된 기록입니다. 앞서 읽은 자료도 나중에 다시 필요할 수 있습니다.'
    replace(first, purpose + '\n\n담당자가 남긴 메모\n' + {
        'demo-0317': '기록 담당 윤서에게 연락이 닿지 않고 작업 목록도 비었습니다. 저는 야간 기록 검토를 맡은 다음 근무자입니다. 외부 유출 여부를 가리고, 남은 자료를 안전하게 복구해야 합니다.',
        'hotel-404': '저는 원격 야간 점검 담당입니다. 서린은 00:04에 프런트 화면에서 살짝 열린 404호 문과 카트를 미는 흰 옷의 사람을 봤습니다. 객실 키는 모두 프런트에 있습니다. 현장에 사람을 보내기 전에 오늘 실제로 열린 문과 영상의 출처부터 가려 주세요.',
        'auction-seven': '저는 마감 검수 담당입니다. 전광판은 MOTH, 결제 요청은 ORBIT를 가리킵니다. 작품은 아직 포장대에 있고 반출은 보류했습니다. 정당한 입찰과 물품·결제를 연결한 뒤에만 인계할 수 있습니다.',
        'encore-last': '저는 공연 기록 검토 담당입니다. 앵콜은 계속 들렸지만 해온은 무대에서 사라졌고 정문 영상에도 보이지 않습니다. 먼저 안전을 확인하고, 관객이 들은 소리와 실제 이동을 가려 정정 안내를 준비해 주세요.',
        'monday-loop': '저는 원격 관측 기록 담당입니다. 나루는 세 번 연속 월요일 화면을 봤다고 합니다. 우유는 줄고 밧줄에는 해초가 붙었습니다. 실제 날짜와 구조 신호의 처리 여부를 확인하고, 원본을 지우지 않는 새 관측 목록을 만들어 주세요.',
    }[cid] + '\n\n업무 폴더에는 담당자가 기록을 대조해 정한 암호가 걸려 있습니다. 암호 규칙은 인계 메모와 각 업무 기록의 끝에 적어 두었습니다. 한 번 연 기록도 지우지 마세요.')
    # Ordinary source names instead of puzzle/question headings.
    for f in c['files']:
        if f['title'].endswith('_자료.txt'):
            f['title'] = f['title'].replace('_자료.txt', '.txt').replace(' ', '_')
        if f['id'] == 'f-photo':
            f.update(type='TEXT', title='시계_대조기록.txt', text='같은 순간에 옮겨 적은 표시 시각\n벽시계 03:10\n기록용 PC 03:17\n점검 구간에 오차는 일정했습니다.')
            for k in ('assetId', 'alt', 'observations'):
                f.pop(k, None)
        if f['id'] == 'auction-seven-f1':
            f['title'] = '입찰_접수표.txt'
        if f['id'] == 'hotel-404-f3':
            f['title'] = 'CAM-404_복도기록.mp4'
        f['title'] = f['title'].replace('.cam', '.mp4')
    walkthrough.append(dict(caseId=cid, versionId=c['versionId'], steps=[]))


def fid(short):
    return short if short.startswith(('f-', 'trash')) else cid + '-' + short


def file(short):
    return next(f for f in c['files'] if f['id'] == fid(short))


def replace(short, text):
    file(short)['text'] = text


def append(short, text):
    file(short)['text'] += '\n\n' + text


def puzzle(n, answer, rule, rule_source, sources, reasoning):
    p = c['puzzles'][n-1]
    rule = f'「{names[n-1]}」 폴더 암호: ' + rule
    append(rule_source, rule)
    evidence = list(dict.fromkeys([fid(rule_source), *[fid(s) for s in sources]]))
    p.update(answer=answer, title=f'{names[n-1]}의 인계 규칙에 맞춰 기록을 대조하세요.', evidenceIds=evidence, hints=[
        rule,
        reasoning, f'정답: {answer}'])
    walkthrough[-1]['steps'].append(dict(folder=names[n-1], answer=answer, ruleSource=fid(rule_source), sources=evidence, reasoning=reasoning))


def finish(title, action, text):
    c['endings'][0].update(title=title, text=text, revisitable=False)
    # The locked final folder performs the action. No post-hoc multiple choice.
    c['rules'][-1]['then'].append(dict(type='END_CASE', id=c['endings'][0]['id']))
    c['rules'][-1]['when'] = dict(type='ALL', conditions=[dict(type='PUZZLE_SOLVED', id=p['id']) for p in c['puzzles']])
    c['hypotheses'][0]['label'] = action
    c['messages'][-1]['text'] = text.split('\n\n')[0]
    for f in c['files']:
        if f.get('clueId'):
            clue = next(cl for cl in c['clues'] if cl['id'] == f['clueId'])
            clue.update(title=f['title'], description='원본 기록과 인계 메모를 대조해 확인할 자료입니다.')
    walkthrough[-1]['resolution'] = action


